/**
 * THE COMPUTE BILLING INVARIANT
 *
 *   `no compute row may stay open unless its sandbox is PROVABLY alive`
 *
 * Closing the meter used to be the responsibility of every individual stop path
 * — the reaper idle-stop, the reaper reconcile, the provider webhook, the
 * explicit user stop, session end/delete, the in-place restart, hibernate, the
 * error/teardown path, account deletion. Every one of them calls
 * `pauseComputeSession(...).catch(warn)` and then flips the sandbox row anyway,
 * so ONE transient failure at pause time strands that billing row forever, and
 * one caller passing the wrong id (session-lifecycle/actions.ts passed a
 * sessionId where a sandboxId was required) strands every row it touches.
 * Nothing ever re-checked. Measured live 2026-07-29: 17 open, still-accruing
 * compute rows whose own `session_sandboxes` row already said `stopped`/`error`
 * — 5,587 sandbox-hours, the worst two at 829h (34.5 days) each.
 *
 * The N-caller design is why this class of bug keeps regressing (2026-06-21,
 * 2026-07-07/#4228, 2026-07-29). So the fast paths stay as an optimisation, but
 * correctness rests on the two mechanisms here and in
 * billing/services/compute-liveness.ts, neither of which asks any caller to
 * remember anything:
 *
 *   1. SETTLEMENT IS EVIDENCE-BOUNDED. A window can never bill past the last
 *      control-plane observation of liveness plus the provider's own auto-stop
 *      ceiling, so a stranded row simply stops accruing on its own.
 *   2. THE SWEEP (compute-invariant-sweep.ts) re-derives, from scratch every
 *      pass, whether each open row still has a provably-alive sandbox, and
 *      closes the ones that do not.
 *
 * Adding a tenth `pauseComputeSession` call site is not how this gets fixed.
 *
 * This module is the PURE half: what to close, and how far to bill it. No `db`,
 * no provider adapters, so the money semantics are exhaustively unit-testable.
 */

import type { SandboxStatus } from '../../platform/providers/status';
import { billableWindowEnd } from './compute-liveness';

export type ComputeCloseReason =
  | 'sandbox-row-missing'
  | 'sandbox-not-active'
  | 'runtime-start-failed'
  | 'beyond-liveness-ceiling'
  | 'provider-not-running'
  | 'unresolvable-past-ceiling'
  | 'window-past-max';

export interface ComputeCloseDecision {
  reason: ComputeCloseReason | null;
  /** Which of the provider round-trips this decision needed. DB-only rules
   *  resolve to false so the common leak costs zero provider calls. */
  needsProviderStatus: boolean;
}

/**
 * The single authority on whether an open compute window must be closed.
 *
 * Rule order is deliberate: every DB-only rule is evaluated FIRST, so the
 * dominant real-world leak (a sandbox row we already marked stopped) is caught
 * without a provider round-trip — which matters because in live prod 44 of 66
 * open rows answered `unknown` from the provider, i.e. `unknown` is the steady
 * state for a box that has been deleted out from under us, not a transient.
 *
 * `unknown` may justify not KILLING a box (we might fight a wake). It can never
 * justify continuing to CHARGE for one, so an unresolvable box stops billing
 * once it has been continuously unresolvable past the ceiling. And no window may
 * exceed `maxWindowMs` under any circumstances — that is the rule that makes a
 * 829-hour row impossible regardless of what anything else claims.
 *
 * Pure so the money semantics are exhaustively unit-tested.
 */
export function decideComputeClose(input: {
  sandboxStatus: string | null;
  hasProviderTarget: boolean;
  runtimeStartFailed: boolean;
  wakeInProgress: boolean;
  providerStatus: SandboxStatus | null;
  unresolvedForMs: number | null;
  openForMs: number;
  beyondLivenessCeiling: boolean;
  unresolvedCeilingMs: number;
  maxWindowMs: number;
}): ComputeCloseDecision {
  const db_ = (reason: ComputeCloseReason | null): ComputeCloseDecision => ({
    reason,
    needsProviderStatus: false,
  });
  // ── DB-only rules (no provider call) ──
  if (!input.sandboxStatus || !input.hasProviderTarget) return db_('sandbox-row-missing');
  if (input.sandboxStatus !== 'active' && input.sandboxStatus !== 'provisioning') {
    return db_('sandbox-not-active');
  }
  // The wake/provision never produced a running box: the meter was opened
  // optimistically by startComputeSession and the failure path left it open.
  // Billing a box that demonstrably failed to start is never correct.
  if (input.runtimeStartFailed) return db_('runtime-start-failed');
  // Past the evidence ceiling the window can never bill another second (the
  // clamp in settleComputeWindow already guarantees that), so the row is dead
  // weight — close it rather than re-examining it every pass forever.
  if (input.beyondLivenessCeiling) return db_('beyond-liveness-ceiling');
  if (input.openForMs >= input.maxWindowMs) return db_('window-past-max');

  // ── Provider-informed rules ──
  if (input.providerStatus === 'stopped' && input.wakeInProgress) {
    return { reason: null, needsProviderStatus: true };
  }
  if (
    input.providerStatus === 'stopped' ||
    input.providerStatus === 'removed' ||
    input.providerStatus === 'terminal'
  ) {
    return { reason: 'provider-not-running', needsProviderStatus: true };
  }
  if (
    input.providerStatus !== 'running' &&
    input.unresolvedForMs !== null &&
    input.unresolvedForMs >= input.unresolvedCeilingMs
  ) {
    return { reason: 'unresolvable-past-ceiling', needsProviderStatus: true };
  }
  return { reason: null, needsProviderStatus: true };
}

/**
 * A wake/start that demonstrably failed. `resumeStoppedSandbox` stamps
 * `runtimeWakeStartedAt` before kicking the provider and `runtimeWakeFailedAt`
 * + `runtimeWakeError` when that start throws; a later successful wake clears
 * both. A failure stamp that is not older than the wake it belongs to means the
 * box never came up — observed in prod with the meter still accruing behind it.
 */
export function hasFailedRuntimeStart(metadata: Record<string, unknown> | null): boolean {
  const failedAt =
    typeof metadata?.runtimeWakeFailedAt === 'string'
      ? Date.parse(metadata.runtimeWakeFailedAt)
      : Number.NaN;
  if (!Number.isFinite(failedAt)) return false;
  const startedAt =
    typeof metadata?.runtimeWakeStartedAt === 'string'
      ? Date.parse(metadata.runtimeWakeStartedAt)
      : Number.NaN;
  return !Number.isFinite(startedAt) || failedAt >= startedAt;
}

/**
 * When the final billed window should END for each close reason — "bill only
 * time we can affirmatively evidence the box was alive" rather than wall-clock
 * up to whenever we happened to notice. `settleComputeWindow` clamps a window
 * end at/behind `last_billed_at` to a zero-cost settle, so an already-debited
 * amount is never re-charged and never auto-refunded (refunds stay a human
 * decision — see scripts/reimburse-compute-leak.ts).
 */
export function computeCloseWindowEnd(input: {
  reason: ComputeCloseReason;
  now: Date;
  startedAt: Date;
  sandboxUpdatedAt: Date | null;
  unresolvedSince: Date | null;
  runtimeWakeFailedAt: Date | null;
  lastAliveAt: Date;
  livenessGraceMs: number;
  maxWindowMs: number;
}): Date {
  const clamp = (d: Date | null): Date => {
    if (!d || Number.isNaN(d.getTime())) return input.now;
    if (d.getTime() < input.startedAt.getTime()) return input.startedAt;
    return d.getTime() > input.now.getTime() ? input.now : d;
  };
  const byReason = (): Date => {
    switch (input.reason) {
      // We recorded the stop when we flipped the sandbox row — bill to then, not
      // to the 34 days later that we noticed.
      case 'sandbox-not-active':
        return clamp(input.sandboxUpdatedAt);
      case 'runtime-start-failed':
        return clamp(input.runtimeWakeFailedAt);
      // The last moment the box was affirmatively resolvable.
      case 'unresolvable-past-ceiling':
        return clamp(input.unresolvedSince);
      case 'window-past-max':
        return clamp(new Date(input.startedAt.getTime() + input.maxWindowMs));
      default:
        return input.now;
    }
  };
  // Whatever the reason argues for, the evidence ceiling always wins: a box
  // cannot outlive its last observed liveness by more than the provider's own
  // auto-stop. This makes the close reason an optimisation rather than a
  // correctness requirement — get the reason wrong and the bill is still capped.
  return clamp(
    billableWindowEnd({
      requestedEnd: byReason(),
      lastAliveAt: input.lastAliveAt,
      graceMs: input.livenessGraceMs,
    }),
  );
}

import { logForDebugging } from '../utils/debug.js'
import {
  isAtOrUnder,
  normalizePathForSandbox,
  pathSpellings,
  properAncestors,
  walkGlobPattern,
} from './sandbox-utils.js'

/**
 * A read-deny glob still needing more than this many mounts after collapsing
 * is logged at warn level (SRT_DEBUG) as a hint that the pattern is broad.
 * The expansion is never truncated, which would silently un-deny paths.
 */
const READ_DENY_GLOB_MOUNT_WARN_THRESHOLD = 256

/** The directory holding `p`, or '' for a root child. */
function parentOf(p: string): string {
  return p.slice(0, p.lastIndexOf('/'))
}

/**
 * Reduce the places a read-deny glob's matches really live to the ones whose
 * mount changes what the sandbox can read. A location is dropped only when a
 * kept proper ancestor's tmpfs already hides it and no re-exposer sits at the
 * ancestor or between the two.
 */
function collapseReadDenyLocations({
  locations,
  reExposedPaths,
}: {
  /** Absolute, symlink-free, trailing-slash-free paths. */
  locations: Iterable<string>
  /** allowRead/allowWrite paths the denyRead loop binds back over a tmpfs, as
   *  spelled and as resolved. */
  reExposedPaths: ReadonlySet<string>
}): Set<string> {
  // A proper ancestor is a proper string prefix, so lexicographic order
  // visits every ancestor before its descendants.
  const sorted = [...new Set(locations)].sort()
  const kept = new Set<string>()
  for (const location of sorted) {
    let reExposedBetween = reExposedPaths.has(location)
    let hidden = false
    for (const ancestor of properAncestors(location)) {
      // A re-exposer at the kept ancestor counts: the deny loop binds it back
      // over the tmpfs, so everything beneath needs its own mount.
      if (reExposedPaths.has(ancestor)) reExposedBetween = true
      if (kept.has(ancestor)) {
        hidden = true
        break
      }
    }
    if (!hidden || reExposedBetween) kept.add(location)
  }
  return kept
}

/**
 * Expand a read-deny glob into the paths bwrap should mount over, collapsed
 * against `reExposedPaths` (the caller's allowRead and allowWrite entries).
 * A pattern ending in `/**` also takes its directory form, so
 * `**\/build/**` yields one mount per `build/` directory. A match reached
 * through a symlink is listed where it really lives, and a directory the walk
 * could not list is denied whole. Sorted, so an ancestor precedes its
 * descendants.
 *
 * @param unlistableDirs - receives the returned locations that hide something
 * the walk could not enumerate, whether by being that directory or by
 * covering it. The Linux wrapper binds nothing back beneath one: what the
 * pattern matches under an allowed path in there was never found, and would
 * come back unmasked.
 */
export function expandReadDenyGlobLinux(
  globPattern: string,
  reExposedPaths: readonly string[],
  unlistableDirs?: Set<string>,
): string[] {
  const walk = walkGlobPattern(globPattern, {
    withDirectoryForm: true,
    followSymlinkedDirectories: true,
  })
  // Where a path the walk reported really lives: the denyRead loop mounts an
  // entry there, whatever spelling named it.
  const locationOf = (p: string): string => walk.realOf.get(p) ?? p
  // An unlisted directory hides whatever the pattern matches beneath it.
  const candidates = new Set([...walk.matches, ...walk.unlisted])
  if (walk.directoryMatches.length > 0) {
    // Everything beneath a directory-form match is itself a match (the
    // pattern ends in /**), so a directory with something to deny holds one.
    // An empty one gets no mount: it has nothing to deny, and as a tmpfs it
    // would swallow later writes. Compared where they live, since one
    // spelling of a directory is walked and the matches found through it are
    // reported at their real locations.
    const holdMatches = new Set(walk.matches.map(m => parentOf(locationOf(m))))
    for (const dir of walk.directoryMatches) {
      // A directory-form match that is a symlink counts in its own right:
      // one the walk did not list through (a link back up the tree, or a
      // further name for a directory already listed) has no match beneath
      // it, yet denies everything it reaches.
      if (holdMatches.has(locationOf(dir)) || walk.symlinks.has(dir)) {
        candidates.add(dir)
      }
    }
  }

  const locations = new Set<string>()
  /** Which spelling first put a location in the list, for the warning below. */
  const namedBy = new Map<string, string>()
  const addLocation = (location: string, candidate: string): void => {
    locations.add(location)
    if (!namedBy.has(location)) namedBy.set(location, candidate)
  }
  for (const candidate of candidates) {
    if (walk.symlinks.has(candidate) && !walk.realOf.has(candidate)) {
      if (!walk.uninspectableLinks.has(candidate)) {
        // A link that resolves to nothing denies nothing, and bwrap cannot
        // mount on the link itself.
        logForDebugging(
          `[Sandbox Linux] denyRead glob "${globPattern}": ${candidate} does not resolve, skipping`,
        )
        continue
      }
      // A link whose target is there but cannot be looked at: kept under its
      // own spelling, where the denyRead loop's stand-in rule hides the
      // nearest directory above it that can be inspected.
      logForDebugging(
        `[Sandbox Linux] denyRead glob "${globPattern}": ${candidate} leads somewhere that cannot be inspected; denying what holds it`,
        { level: 'warn' },
      )
      addLocation(candidate, candidate)
      continue
    }
    const location = locationOf(candidate)
    if (location !== '/') {
      addLocation(location, candidate)
      continue
    }
    // A link to the root. A tmpfs there would wipe every mount placed before
    // it and the pivot would promote it, booting the command on an empty
    // tree, and bwrap cannot mount on the link itself. The nearest directory
    // above the link stands in for it, as for an entry that cannot be
    // inspected — never the root itself.
    const standIn = locationOf(parentOf(candidate))
    if (standIn === '' || standIn === '/') {
      logForDebugging(
        `[Sandbox Linux] denyRead glob "${globPattern}": ${candidate} resolves to / and nothing but / holds it, skipping`,
        { level: 'warn' },
      )
      continue
    }
    logForDebugging(
      `[Sandbox Linux] denyRead glob "${globPattern}": ${candidate} resolves to /; denying ${standIn}, which holds it, instead`,
      { level: 'warn' },
    )
    addLocation(standIn, candidate)
  }

  const reExposed = new Set(
    reExposedPaths.flatMap(p => pathSpellings(normalizePathForSandbox(p))),
  )
  const mounts = collapseReadDenyLocations({
    locations,
    reExposedPaths: reExposed,
  })

  // Which mounts stand for something the walk could not enumerate: the
  // unlistable directory itself when it survived the collapse, otherwise the
  // kept ancestor that hides it.
  for (const unlisted of walk.unlisted) {
    const location = locationOf(unlisted)
    if (mounts.has(location)) {
      unlistableDirs?.add(location)
      continue
    }
    for (const ancestor of properAncestors(location)) {
      if (mounts.has(ancestor)) {
        unlistableDirs?.add(ancestor)
        break
      }
    }
  }

  logForDebugging(
    `[Sandbox Linux] Expanded denyRead glob "${globPattern}": ${walk.matches.length} matches -> ${mounts.size} mounts`,
  )
  for (const mount of mounts) {
    // A matched link decides what is hidden for the whole sandbox: a
    // `certs/*` entry pointing at a database directory mounts a tmpfs over
    // that directory, not over anything the pattern names.
    if (walk.baseLocation !== '' && !isAtOrUnder(mount, walk.baseLocation)) {
      logForDebugging(
        `[Sandbox Linux] denyRead glob "${globPattern}" hides ${mount}, outside ${walk.baseLocation}: reached through ${namedBy.get(mount) === mount ? 'a symlinked directory' : namedBy.get(mount)}`,
        { level: 'warn' },
      )
    }
  }
  if (mounts.size > READ_DENY_GLOB_MOUNT_WARN_THRESHOLD) {
    logForDebugging(
      `[Sandbox Linux] denyRead glob "${globPattern}" still needs ${mounts.size} mounts after collapsing ` +
        `(threshold ${READ_DENY_GLOB_MOUNT_WARN_THRESHOLD}); each is a separate bwrap mount at sandbox start. ` +
        `Prefer denying the enclosing directories.`,
      { level: 'warn' },
    )
  }
  return [...mounts].sort()
}

import { describe, it, expect, beforeAll, afterAll } from 'bun:test'
import { spawnSync } from 'node:child_process'
import {
  existsSync,
  mkdirSync,
  readFileSync,
  realpathSync,
  rmSync,
  writeFileSync,
} from 'node:fs'
import { homedir, tmpdir } from 'node:os'
import { join } from 'node:path'
import { wrapCommandWithSandboxMacOS } from '../../src/sandbox/macos-sandbox-utils.js'
import { wrapCommandWithSandboxLinux } from '../../src/sandbox/linux-sandbox-utils.js'
import { createMitmCA, disposeMitmCA } from '../../src/sandbox/mitm-ca.js'
import type {
  FsReadRestrictionConfig,
  FsWriteRestrictionConfig,
} from '../../src/sandbox/sandbox-schemas.js'
import { isLinux, isMacOS, isSupportedPlatform } from '../helpers/platform.js'

/**
 * Tests for the allowRead (allowWithinDeny) feature.
 *
 * allowRead re-allows read access within regions blocked by denyRead.
 * allowRead takes precedence over denyRead — the opposite of write,
 * where denyWrite takes precedence over allowWrite.
 */
describe('allowRead precedence over denyRead', () => {
  const TEST_BASE_DIR = join(tmpdir(), 'allow-read-test-' + Date.now())
  const TEST_DENIED_DIR = join(TEST_BASE_DIR, 'denied')
  const TEST_ALLOWED_SUBDIR = join(TEST_DENIED_DIR, 'allowed')
  const TEST_SECRET_FILE = join(TEST_DENIED_DIR, 'secret.txt')
  const TEST_ALLOWED_FILE = join(TEST_ALLOWED_SUBDIR, 'visible.txt')
  const TEST_SECRET_CONTENT = 'TOP_SECRET'
  const TEST_ALLOWED_CONTENT = 'VISIBLE_DATA'

  beforeAll(() => {
    if (!isSupportedPlatform) return

    mkdirSync(TEST_ALLOWED_SUBDIR, { recursive: true })
    writeFileSync(TEST_SECRET_FILE, TEST_SECRET_CONTENT)
    writeFileSync(TEST_ALLOWED_FILE, TEST_ALLOWED_CONTENT)
  })

  afterAll(() => {
    if (existsSync(TEST_BASE_DIR)) {
      rmSync(TEST_BASE_DIR, { recursive: true, force: true })
    }
  })

  describe('macOS Seatbelt', () => {
    it.if(isMacOS)('should deny reading a file in a denied directory', () => {
      const readConfig: FsReadRestrictionConfig = {
        denyOnly: [TEST_DENIED_DIR],
        allowWithinDeny: [],
      }

      const wrappedCommand = wrapCommandWithSandboxMacOS({
        command: `cat ${TEST_SECRET_FILE}`,
        needsNetworkRestriction: false,
        readConfig,
        writeConfig: undefined,
      })

      const result = spawnSync(wrappedCommand, {
        shell: true,
        encoding: 'utf8',
        timeout: 5000,
      })

      expect(result.status).not.toBe(0)
      expect(result.stdout).not.toContain(TEST_SECRET_CONTENT)
    })

    it.if(isMacOS)(
      'should allow reading a file in an allowWithinDeny subdirectory',
      () => {
        const readConfig: FsReadRestrictionConfig = {
          denyOnly: [TEST_DENIED_DIR],
          allowWithinDeny: [TEST_ALLOWED_SUBDIR],
        }

        const wrappedCommand = wrapCommandWithSandboxMacOS({
          command: `cat ${TEST_ALLOWED_FILE}`,
          needsNetworkRestriction: false,
          readConfig,
          writeConfig: undefined,
        })

        const result = spawnSync(wrappedCommand, {
          shell: true,
          encoding: 'utf8',
          timeout: 5000,
        })

        expect(result.status).toBe(0)
        expect(result.stdout).toContain(TEST_ALLOWED_CONTENT)
      },
    )

    it.if(isMacOS)(
      'should still deny reading files outside the re-allowed subdirectory',
      () => {
        const readConfig: FsReadRestrictionConfig = {
          denyOnly: [TEST_DENIED_DIR],
          allowWithinDeny: [TEST_ALLOWED_SUBDIR],
        }

        const wrappedCommand = wrapCommandWithSandboxMacOS({
          command: `cat ${TEST_SECRET_FILE}`,
          needsNetworkRestriction: false,
          readConfig,
          writeConfig: undefined,
        })

        const result = spawnSync(wrappedCommand, {
          shell: true,
          encoding: 'utf8',
          timeout: 5000,
        })

        expect(result.status).not.toBe(0)
        expect(result.stdout).not.toContain(TEST_SECRET_CONTENT)
      },
    )
  })

  describe('Linux bwrap', () => {
    it.if(isLinux)(
      'should deny reading a file in a denied directory',
      async () => {
        const readConfig: FsReadRestrictionConfig = {
          denyOnly: [TEST_DENIED_DIR],
          allowWithinDeny: [],
        }

        const wrappedCommand = await wrapCommandWithSandboxLinux({
          command: `cat ${TEST_SECRET_FILE}`,
          needsNetworkRestriction: false,
          readConfig,
          writeConfig: undefined,
        })

        const result = spawnSync(wrappedCommand, {
          shell: true,
          encoding: 'utf8',
          timeout: 5000,
        })

        expect(result.status).not.toBe(0)
        expect(result.stdout).not.toContain(TEST_SECRET_CONTENT)
      },
    )

    it.if(isLinux)(
      'should allow reading a file in an allowWithinDeny subdirectory',
      async () => {
        const readConfig: FsReadRestrictionConfig = {
          denyOnly: [TEST_DENIED_DIR],
          allowWithinDeny: [TEST_ALLOWED_SUBDIR],
        }

        const wrappedCommand = await wrapCommandWithSandboxLinux({
          command: `cat ${TEST_ALLOWED_FILE}`,
          needsNetworkRestriction: false,
          readConfig,
          writeConfig: undefined,
        })

        const result = spawnSync(wrappedCommand, {
          shell: true,
          encoding: 'utf8',
          timeout: 5000,
        })

        expect(result.status).toBe(0)
        expect(result.stdout).toContain(TEST_ALLOWED_CONTENT)
      },
    )

    it.if(isLinux)(
      'should still deny reading files outside the re-allowed subdirectory',
      async () => {
        const readConfig: FsReadRestrictionConfig = {
          denyOnly: [TEST_DENIED_DIR],
          allowWithinDeny: [TEST_ALLOWED_SUBDIR],
        }

        const wrappedCommand = await wrapCommandWithSandboxLinux({
          command: `cat ${TEST_SECRET_FILE}`,
          needsNetworkRestriction: false,
          readConfig,
          writeConfig: undefined,
        })

        const result = spawnSync(wrappedCommand, {
          shell: true,
          encoding: 'utf8',
          timeout: 5000,
        })

        expect(result.status).not.toBe(0)
        expect(result.stdout).not.toContain(TEST_SECRET_CONTENT)
      },
    )

    // Regression: the write-path skip check in the allowRead re-bind loop was
    // too broad — it skipped any allowPath under ANY allowWrite, not just
    // writes actually re-bound under this tmpfs. With allowWrite as an
    // ancestor of denyRead (not wiped, not re-bound), allowRead under it was
    // skipped and left sitting in the empty tmpfs.
    // Shape: allowWrite: [~], denyRead: [~/.ssh], allowRead: [~/.ssh/known_hosts].
    it.if(isLinux)(
      'should re-allow under denyRead when allowWrite is an ancestor of the deny',
      async () => {
        const wrappedCommand = await wrapCommandWithSandboxLinux({
          command: `cat ${TEST_ALLOWED_FILE}`,
          needsNetworkRestriction: false,
          readConfig: {
            denyOnly: [TEST_DENIED_DIR],
            allowWithinDeny: [TEST_ALLOWED_SUBDIR],
          },
          writeConfig: {
            allowOnly: [TEST_BASE_DIR], // ancestor of denyRead
            denyWithinAllow: [],
          },
        })

        const result = spawnSync(wrappedCommand, {
          shell: true,
          encoding: 'utf8',
          timeout: 5000,
        })

        expect(result.status).toBe(0)
        expect(result.stdout).toContain(TEST_ALLOWED_CONTENT)
      },
    )
  })
})

/**
 * Regression: denyRead: ['/'] + allowRead: [<project>] used to deny everything.
 *
 * macOS: (subpath "/") denies the root inode; no allowWithinDeny subpath covers
 *   "/", so dyld SIGABRTs before exec. Fix emits (allow file-read* (literal "/")).
 * Linux: --tmpfs / wiped all prior mounts, and the carve-out prefix check
 *   startsWith('/' + '/') never matched. Fix expands '/' into its children.
 *
 * Test dir lives under $HOME (not tmpdir) so the macOS /tmp → /private/tmp
 * symlink doesn't confuse Seatbelt path matching.
 */
describe('allowRead carve-out with denyRead at filesystem root (issue #10)', () => {
  const TEST_DIR = join(
    homedir(),
    '.sandbox-runtime-test-root-deny-' + Date.now(),
  )
  const TEST_FILE = join(TEST_DIR, 'visible.txt')
  const TEST_CONTENT = 'ROOT_CARVE_OUT'
  // Paths needed for sh/cat to load at all when the whole filesystem is denied.
  // /private covers /tmp and /var (macOS symlinks). /lib* for Linux ld.so.
  const EXEC_DEPS = [
    '/bin',
    '/usr',
    '/lib',
    '/lib64',
    '/System',
    '/private',
    '/dev',
    '/etc',
  ]

  beforeAll(() => {
    if (!isSupportedPlatform) return
    mkdirSync(TEST_DIR, { recursive: true })
    writeFileSync(TEST_FILE, TEST_CONTENT)
  })

  afterAll(() => {
    if (existsSync(TEST_DIR)) {
      rmSync(TEST_DIR, { recursive: true, force: true })
    }
  })

  it.if(isMacOS)('macOS: re-allows carve-out under a root-level deny', () => {
    const readConfig: FsReadRestrictionConfig = {
      denyOnly: ['/'],
      allowWithinDeny: [TEST_DIR, ...EXEC_DEPS],
    }

    // EXEC_DEPS covers /bin and /usr but not /opt/homebrew — pin the shell
    // so denying the filesystem root doesn't break execvp on Homebrew-bash Macs.
    const wrappedCommand = wrapCommandWithSandboxMacOS({
      command: `cat ${TEST_FILE}`,
      needsNetworkRestriction: false,
      readConfig,
      writeConfig: undefined,
      binShell: '/bin/bash',
    })

