    it('rm of a non-denied file', () => {
      const target = join(PROJECT, 'deleteme.txt')
      const r = run(`rm ${target}`, PROJECT_READ(), PROJECT_WRITE())
      expect(r.status).toBe(0)
      expect(existsSync(target)).toBe(false)
